    `,this.overlay.appendChild(this.panel),this.container.appendChild(this.overlay),this.overlay.addEventListener("click",e=>{e.target===this.overlay&&this.close()})}toggle(){this.isOpen?this.close():this.open()}open(e){e&&this.npcManager.getNpc(e)&&(this.selectedNpcId=e),this.isOpen=!0,this.overlay.style.display="flex",y.playLevelUp(),this.render()}close(){this.isOpen=!1,this.overlay.style.display="none"}render(){const e=this.npcManager.getAllNpcs(),t=this.npcManager.getNpc(this.selectedNpcId)||e[0],i=this.npcManager.getState(t.id),s=this.npcManager.getHearts(t.id),o=this.contextProvider?.(t.id)||null;this.panel.innerHTML=`
